const body = $input.first().json.body || $input.first().json;

const productName = body.product_name || body.productName || '';
const brand = body.brand || '';
const category = body.category || '';
const subcategory = body.subcategory || '';
const ean = body.ean || '';

if (!productName) throw new Error('product_name is required');

const baseData = {
  product_name: productName,
  brand: brand,
  ean: ean,
  category: category,
  subcategory: subcategory,
  unit: body.unit || '',
  wholesale_qty: body.wholesale_qty || body.wholesaleQty || '',
  price_wholesale: body.price_wholesale || body.priceWholesale || '',
  price_retail: body.price_retail || body.priceRetail || '',
  cost_price: body.cost_price || body.costPrice || '',
  added_by: body.added_by || body.addedBy || '',
  communets_code: body.communets_code || body.communetsCode || '',
  status: body.status || 'Active',
  stock_qty: body.stock_qty || body.stockQty || '',
  vendor_details: body.vendor_details || body.vendorDetails || '',
  vendor_contact: body.vendor_contact || body.vendorContact || '',
  image_url: body.image_url || '',
  image_url_2: body.image_url_2 || '',
  image_url_3: body.image_url_3 || '',
  image_url_4: body.image_url_4 || '',
};

return [{json: baseData}];

const prev = $('Extract User Input').first().json;

const productName = prev.product_name || '';
const brand = prev.brand || '';
const category = prev.category || '';
const subcategory = prev.subcategory || '';
const ean = prev.ean || '';

const baseData = {
  product_name: productName,
  brand: brand,
  ean: ean,
  category: category,
  subcategory: subcategory,
  unit: prev.unit || '',
  wholesale_qty: prev.wholesale_qty || '',
  price_wholesale: prev.price_wholesale || '',
  price_retail: prev.price_retail || ''
};

const queries = [
  `${brand} ${productName} technical specifications datasheet`,
  `${ean ? ean + ' ' : ''}${productName} ${subcategory || category} features details`
].filter(q => q.trim().length > 5);

return queries.map((q, i) => ({ json: { ...baseData, query: q, queryIndex: i } }));

const allItems = $input.all();
const userData = $('Extract User Input').first().json;

const baseData = {
  product_name: userData.product_name,
  brand: userData.brand,
  ean: userData.ean,
  category: userData.category,
  subcategory: userData.subcategory,
  unit: userData.unit,
  wholesale_qty: userData.wholesale_qty,
  price_wholesale: userData.price_wholesale,
  price_retail: userData.price_retail
};

const urlSet = new Set();
const results = [];

const skipDomains = ['wikipedia.org','reddit.com','youtube.com','facebook.com',
  'twitter.com','instagram.com','pinterest.com','quora.com','linkedin.com'];

for (const item of allItems) {
  const searchItems = item.json.organic || [];
  for (const r of searchItems) {
    const url = r.link;
    if (!url || urlSet.has(url)) continue;
    if (skipDomains.some(d => url.includes(d))) continue;
    urlSet.add(url);
    results.push({ url, title: r.title || '', snippet: r.snippet || '' });
  }
}

return [{ json: { ...baseData, urls: results, total_found: results.length } }];

const data = $input.first().json;
const allUrls = data.urls || [];

// Separate PDFs from scrapeable URLs
const pdfSnippets = [];
const scrapeable = [];

for (const urlObj of allUrls) {
  const u = (urlObj.url || '').toLowerCase();
  if (u.match(/\.pdf($|\?|#)/)) {
    pdfSnippets.push('PDF: ' + (urlObj.title || '') + ' — ' + (urlObj.snippet || ''));
  } else {
    scrapeable.push(urlObj);
  }
}

// Take top 3 non-PDF URLs
const topUrls = scrapeable.slice(0, 3);

// Pass PDF snippets as supplementary context
const pdfContext = pdfSnippets.join('\n');

// FIX: fallback if no URLs
if (topUrls.length === 0) {
  return [{
    json: {
      ...data,
      pdf_context: pdfContext,
      scrape_url: null,
      scrape_index: -1,
      snippet_data: null,
      no_urls_found: true
    }
  }];
}

// Normal flow
return topUrls.map((urlObj, i) => ({
  json: {
    ...data,
    pdf_context: pdfContext,
    scrape_url: urlObj.url,
    scrape_index: i,
    snippet_data: {
      url: urlObj.url,
      title: urlObj.title || 'N/A',
      snippet: urlObj.snippet || 'No snippet available'
    }
  }
}));

const rawInput = $input.first().json;
const aiText = rawInput.text || rawInput.response || rawInput.output || '';
const userInput = $('Extract User Input').first().json;

let generatedContent = {};

function tryParse(s) {
  try { return JSON.parse(s); } catch(_) { return null; }
}

function extractAndRepairJSON(raw) {
  if (!raw || typeof raw !== 'string') return null;

  let s = raw.replace(/```json\s*/gi, '').replace(/```\s*/gi, '').trim();

  let start = s.indexOf('{');
  let end = s.lastIndexOf('}');

  if (start === -1) {
    s = '{' + s;
    start = 0;
    end = s.lastIndexOf('}');
  }

  if (start !== -1 && end > start) {
    s = s.substring(start, end + 1);
  } else if (start !== -1) {
    s = s.substring(start);
  }

  let result = tryParse(s);
  if (result) return result;

  s = s.replace(/(?<=\":[\s]*\"[^\"]*)\n(?=[^\"]*\")/g, ' ');
  s = s.replace(/,\s*([}\]])/g, '$1');
  s = s.replace(/[\u201C\u201D]/g, '"').replace(/[\u2018\u2019]/g, "'");

  result = tryParse(s);
  if (result) return result;

  let ob = 0, oq = 0, inStr = false, escape = false;
  for (const c of s) {
    if (escape) { escape = false; continue; }
    if (c === '\\') { escape = true; continue; }
    if (c === '"') { inStr = !inStr; continue; }
    if (inStr) continue;
    if (c === '{') ob++; if (c === '}') ob--;
    if (c === '[') oq++; if (c === ']') oq--;
  }
  while (oq > 0) { s += ']'; oq--; }
  while (ob > 0) { s += '}'; ob--; }

  result = tryParse(s);
  if (result) return result;

  const lc = s.lastIndexOf(',\n');
  if (lc > 50) {
    let tr = s.substring(0, lc);
    ob = 0; oq = 0;
    for (const c of tr) {
      if (c === '{') ob++; if (c === '}') ob--;
      if (c === '[') oq++; if (c === ']') oq--;
    }
    while (oq > 0) { tr += ']'; oq--; }
    while (ob > 0) { tr += '}'; ob--; }
    result = tryParse(tr);
    if (result) return result;
  }

  return null;
}

try {
  const aiString = typeof aiText === 'string' ? aiText : JSON.stringify(aiText);
  generatedContent = extractAndRepairJSON(aiString) || {};
} catch(e) {
  generatedContent = {};
}

return [{
  json: {
    user_input: {
      product_name: userInput.product_name || '',
      brand: userInput.brand || '',
      ean: userInput.ean || '',
      category: userInput.category || '',
      subcategory: userInput.subcategory || '',
      unit: userInput.unit || '',
      wholesale_qty: userInput.wholesale_qty || '',
      price_wholesale: userInput.price_wholesale || '',
      price_retail: userInput.price_retail || ''
    },
    generated_content: {
      seo_title: generatedContent.seo_title || userInput.product_name || '',
      overview: generatedContent.overview || '',
      features: Array.isArray(generatedContent.features) ? generatedContent.features : [],
      detailed_description: generatedContent.detailed_description || '',
      specs: Array.isArray(generatedContent.specs) ? generatedContent.specs : []
    }
  }
}];

const scrapedItems = $input.all();
const originalItems = $('Select Scrape URLs').all();
const userData = $('Extract User Input').first().json;
const aggData = $('Aggregate URLs').first().json;

const baseData = {
  product_name: userData.product_name,
  brand: userData.brand,
  ean: userData.ean,
  category: userData.category,
  subcategory: userData.subcategory,
  unit: userData.unit,
  wholesale_qty: userData.wholesale_qty,
  price_wholesale: userData.price_wholesale,
  price_retail: userData.price_retail,
  urls: aggData.urls || []
};

function isBinaryOrPdf(text, url) {
  if (!text) return false;
  if (url && url.toLowerCase().includes('.pdf')) return true;
  if (text.startsWith('%PDF')) return true;
  const sample = text.substring(0, 300);
  const nonPrint = (sample.match(/[\x00-\x08\x0E-\x1F\x7F]/g) || []).length;
  return nonPrint / Math.max(sample.length, 1) > 0.1;
}

let scrapedTexts = '';
let successCount = 0;

scrapedItems.forEach((item, i) => {
  const orig = originalItems[i]?.json || {};
  const url = orig.scrape_url || 'unknown';
  const snippetData = orig.snippet_data || {};
  const fallbackSnippet = snippetData.snippet || snippetData.title || '';

  let rawBody = item.json.data || item.json.body || '';
  if (typeof rawBody !== 'string') rawBody = JSON.stringify(rawBody);

  if (isBinaryOrPdf(rawBody, url)) {
    scrapedTexts += `\n\n--- SOURCE ${i+1} (${url}) ---\nPDF/Binary file. Key info from snippet: ${fallbackSnippet}`;
    return;
  }

  let cleanText = rawBody
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;|\u00a0/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const blockedSignals = ['Access Denied','Attention Required','enable JavaScript',
    'Enable cookies','Cloudflare','403 Forbidden','429 Too Many','robot check'];
  const isBlocked = cleanText.length < 200 ||
    blockedSignals.some(k => cleanText.toLowerCase().includes(k.toLowerCase()));

  if (isBlocked) {
    scrapedTexts += `\n\n--- SOURCE ${i+1} (${url}) ---\nScraping blocked. Key info from snippet: ${fallbackSnippet}`;
  } else {
    successCount++;
    scrapedTexts += `\n\n--- SOURCE ${i+1} (${url}) ---\n${cleanText.substring(0, 8000)}`;
  }
});

const pdfContext = originalItems[0]?.json?.pdf_context || '';
if (pdfContext) {
  scrapedTexts += '\n\n--- PDF SOURCES (not scraped, snippet only) ---\n' + pdfContext;
}

if (successCount < 2) {
  const allUrls = baseData.urls || [];
  if (allUrls.length > 0) {
    let extra = '\n\n--- SUPPLEMENTARY CONTEXT FROM SEARCH RESULTS ---\n';
    extra += '(Use these titles and snippets to generate the product description)\n';
    allUrls.slice(0, 25).forEach((u, idx) => {
      if (u.snippet || u.title) {
        extra += `\n[${idx+1}] ${u.title || ''}\n${u.snippet || ''}`;
      }
    });
    scrapedTexts += extra;
  }
}

return [{ json: { ...baseData, scraped_texts: scrapedTexts, scrape_success_count: successCount } }];

